WITH session_summary AS (SELECT session_id, SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END) AS product_count, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count FROM web_events GROUP BY session_id) SELECT s.id, s.customer_id, ss.product_count, ss.purchase_count FROM sessions s JOIN session_summary ss ON s.id = ss.session_id WHERE ss.purchase_count > 4 ORDER BY s.customer_id DESC, id LIMIT 10;
